import{_ as t,o,c as r,a7 as a}from"./chunks/framework.C4ZIv4ii.js";const s="/falconcms/screenshots/wholesale-product-page.webp",g=JSON.parse('{"title":"Falcon Wholesale","description":"","frontmatter":{},"headers":[],"relativePath":"wholesale/overview.md","filePath":"wholesale/overview.md","lastUpdated":1792170474000}'),i={name:"wholesale/overview.md"};function n(l,e,h,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="falcon-wholesale" tabindex="-1">Falcon Wholesale <a class="header-anchor" href="#falcon-wholesale" aria-label="Permalink to &quot;Falcon Wholesale&quot;">​</a></h1><p><strong>Falcon Wholesale</strong> turns the Falcon shop into a wholesale and B2B store, alongside your retail one. Businesses apply for a trade account, you approve them, and from then on they see their own prices, buy in the quantities you set, and order from a portal of their own. Retail shoppers and guests see the shop exactly as before.</p><div class="tip custom-block"><p class="custom-block-title">Pro feature</p><p>Falcon Wholesale is part of <strong>FalconCMS Pro</strong> (the Pro and Agency plans). It ships inside the Pro package and arrives with a Pro update. See <a href="/falconcms/guide/pro.html">Installing Pro</a>.</p></div><p><img src="'+s+'" alt="A product page as a wholesale customer sees it: the wholesale price, the saving, the minimum and maximum order, and a quantity tier picker"></p><p><em>What a signed-in wholesale customer sees on a product page: their price with retail struck through, the saving, the minimum and maximum order, and the quantity tiers as a picker tied to the quantity box.</em></p><hr><h2 id="what-you-can-do-with-it" tabindex="-1">What you can do with it <a class="header-anchor" href="#what-you-can-do-with-it" aria-label="Permalink to &quot;What you can do with it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What&#39;s included</th></tr></thead><tbody><tr><td><strong>Customers</strong></td><td>An application form with approval (manual or automatic), customer levels, a Wholesale Customer role, company accounts with several buyers</td></tr><tr><td><strong>Prices</strong></td><td>A price per level for each product and each variation, category discounts, a level discount, quantity tiers, mix &amp; match, contract prices for one company</td></tr><tr><td><strong>Who sees what</strong></td><td>Wholesale-only or retail-only products, prices hidden from guests or from everyone but trade customers, a fully private store</td></tr><tr><td><strong>Ordering rules</strong></td><td>Minimum quantity, pack size and maximum per product; minimum order value and item count per level</td></tr><tr><td><strong>Checkout</strong></td><td>Payment and shipping methods per level, free shipping from an amount, deposits, spend discounts, PO numbers, tax exemption, buying on account (credit)</td></tr><tr><td><strong>Self-service</strong></td><td>A wholesale login page, a portal with quick order, order again, a price list, saved lists, quotes, invoices and an account statement</td></tr><tr><td><strong>Running it</strong></td><td>Approval of company buyers&#39; orders, sales reps with commission, reports, text messages (SMS), price import and export as CSV</td></tr></tbody></table><hr><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>FalconCMS Pro</strong> with an active licence. Without one the plugin loads nothing.</li><li>The <strong>Falcon Shop</strong> plugin switched on (it is on by default; see <a href="/falconcms/ecommerce/shop-plugin.html">Shop Plugin &amp; Templates</a>).</li><li><strong>FalconCMS 2.8.1 or newer.</strong> On an older core the plugin shows a notice and changes nothing.</li></ul><h2 id="switching-it-on" tabindex="-1">Switching it on <a class="header-anchor" href="#switching-it-on" aria-label="Permalink to &quot;Switching it on&quot;">​</a></h2><ol><li>Install or update Pro, then open <strong>Plugins</strong>.</li><li>Find <strong>Falcon Wholesale</strong> and click <strong>Activate</strong>.</li></ol><p>Activation sets up three things for you:</p><ul><li>a customer level called <strong>Wholesale</strong>, set as the default level;</li><li>the <strong>Wholesale Customer</strong> role, which approved trade customers get beside their own role;</li><li>a page called <strong>Wholesale Login</strong> at <code>/wholesale-login</code>, holding the login form.</li></ul><p>A <strong>Wholesale</strong> menu appears in the admin sidebar, under the shop:</p><table tabindex="0"><thead><tr><th>Screen</th><th>What it is for</th></tr></thead><tbody><tr><td><strong>Customers</strong></td><td>Applications and approved accounts, with each customer&#39;s details, credit and contract prices</td></tr><tr><td><strong>Quotes</strong></td><td>Quote requests from the cart, which you price and send</td></tr><tr><td><strong>Levels</strong></td><td>The kinds of trade customer (Wholesale, Dealer, Distributor…) and what each one gets</td></tr><tr><td><strong>Reports</strong></td><td>Wholesale revenue, top customers and products, what is owed, and quiet customers</td></tr><tr><td><strong>Import / export</strong></td><td>Every wholesale price, minimum and pack size as one CSV file</td></tr><tr><td><strong>Settings</strong></td><td>Applications, who sees prices, private store, checkout options, invoices, credit, SMS and sales reps</td></tr></tbody></table><hr><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>A working wholesale shop in five steps:</p><ol><li><strong>Check the settings.</strong> Open <strong>Wholesale → Settings</strong>. The defaults are sensible: applications are accepted and wait for your approval, coupons and automatic promotions are off for wholesale prices, and a wholesale customer never pays more than a retail sale price. See <a href="/falconcms/wholesale/settings.html">Settings</a>.</li><li><strong>Set your levels.</strong> <strong>Wholesale → Levels</strong> already has <em>Wholesale</em>. Give it a discount off retail, or leave 0 and price products yourself. Add more levels (Dealer, Distributor) if different customers get different terms. See <a href="/falconcms/wholesale/customers.html#levels">Customers &amp; Levels</a>.</li><li><strong>Price a product.</strong> Open a product and its <strong>Wholesale</strong> tab: a price per level, quantity tiers, a minimum quantity and a pack size. See <a href="/falconcms/wholesale/pricing.html">Prices</a>.</li><li><strong>Tell trade customers where to apply.</strong> Link to <code>/wholesale/apply</code> (or add the <code>[falcon_wholesale_apply]</code> shortcode to a page), and to the <strong>Wholesale Login</strong> page.</li><li><strong>Approve applications</strong> in <strong>Wholesale → Customers</strong>. The customer is emailed, signs in, and sees their prices everywhere in the shop.</li></ol><hr><h2 id="how-a-wholesale-customer-gets-their-price" tabindex="-1">How a wholesale customer gets their price <a class="header-anchor" href="#how-a-wholesale-customer-gets-their-price" aria-label="Permalink to &quot;How a wholesale customer gets their price&quot;">​</a></h2><p>For a signed-in, approved customer, the price of a product comes from the <strong>first</strong> of these that has a value:</p><ol><li>a line from a <strong>quote</strong> they accepted keeps the quoted price in the cart</li><li>a <strong>contract price</strong> for their company (per product or per variation) — final, no tiers on top</li><li>the <strong>variation&#39;s</strong> wholesale price for their level (variable products)</li><li>the <strong>product&#39;s</strong> wholesale price for their level (simple products)</li><li>the biggest <strong>category discount</strong> for their level, off the regular price</li><li>their <strong>level&#39;s discount</strong>, off the regular price</li></ol><p>Then, from 3 to 6, the <strong>quantity tier</strong> the cart quantity reaches, if the product has tiers. The full rules, with mix &amp; match and &quot;never more than retail&quot;, are on the <a href="/falconcms/wholesale/pricing.html">Prices</a> page.</p><p>Retail shoppers and guests are never affected. Prices that depend on the customer are shown only to signed-in customers, and those never get a cached page.</p><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/falconcms/wholesale/customers.html">Customers &amp; Levels</a> — applications, approval, levels, company accounts, sales reps</li><li><a href="/falconcms/wholesale/pricing.html">Prices</a> — product, variation, category and contract prices, tiers, visibility</li><li><a href="/falconcms/wholesale/ordering.html">Ordering &amp; Checkout</a> — minimums, packs, payment and shipping per level, deposits, credit, quotes</li><li><a href="/falconcms/wholesale/portal.html">Login &amp; Portal</a> — the login page, the portal, quick order, invoices</li><li><a href="/falconcms/wholesale/settings.html">Settings &amp; Tools</a> — every setting, SMS, emails, reports, CSV import</li><li><a href="/falconcms/wholesale/developers.html">For Developers</a> — hooks, shortcodes and data</li></ul>',30)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
